55	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
76	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
83	     * new owner's id, customerCode, registrationDate and membershipLevel.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    /**
88	     * Common street-type abbreviations expanded during address normalization, keyed by the
89	     * upper-cased abbreviation.
90	     */
91	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
92	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
93	
94	    /**
95	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
96	     * city already holds this many owners.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * Maximum number of owners that may be created on a single day. A create is rejected once this
102	     * many owners already carry the current day as their {@code registrationDate}.
103	     */
104	    private static final int DAILY_OWNER_LIMIT = 100;
105	
106	    private final ClinicService clinicService;
107	
108	    private final OwnerMapper ownerMapper;
109	
110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    public OwnerRestControllerV1(ClinicService clinicService,
115	                                 OwnerMapper ownerMapper,
116	                                 PetMapper petMapper,
117	                                 VisitMapper visitMapper) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        validateRequiredFields(ownerFieldsDto);
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
156	        LocalDate effectiveDate = owner.getRegistrationDate() == null
157	            ? LocalDate.now()
158	            : owner.getRegistrationDate();
159	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
160	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
161	        rejectWhenCityAtCapacity(owner.getCity());
162	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
163	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
164	        rejectDuplicateTelephone(telephone);
165	        owner.setTelephone(telephone);
166	        String email = normalizeEmail(ownerFieldsDto.getEmail());
167	        rejectDuplicateEmail(email);
168	        owner.setEmail(email);
169	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
170	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
171	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
172	        this.clinicService.saveOwner(owner);
173	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
174	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
175	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
176	            ownerDto.getMembershipLevel());
177	        headers.setLocation(UriComponentsBuilder.newInstance()
178	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
179	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
180	    }
181	
182	    /**
183	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
184	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
185	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
186	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
187	     *
188	     * @param city     the owner's city
189	     * @param lastName the owner's last name
190	     * @return the assigned customer code
191	     */
192	    private String nextCustomerCode(String city, String lastName) {
193	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
194	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
195	        int sequence = (int) this.clinicService.findAllOwners().stream()
196	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
197	            .count() + 1;
198	        return String.format("%s-%s-%04d", city3, last3, sequence);
199	    }
200	
201	    /**
202	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
203	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
204	     *
205	     * @param customerCode     the owner's assigned customer code
206	     * @param registrationDate the owner's registration date
207	     * @return the assigned membership number
208	     */
209	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
210	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
211	    }
212	
213	    /**
214	     * Counts the existing owners that already share the given firstName and lastName, compared
215	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
216	     * the owners that pre-existed this create.
217	     *
218	     * @param firstName the new owner's first name
219	     * @param lastName  the new owner's last name
220	     * @return the number of existing namesakes
221	     */
222	    private int countNamesakes(String firstName, String lastName) {
223	        return (int) this.clinicService.findAllOwners().stream()
224	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
225	                && equalsIgnoreCase(existing.getLastName(), lastName))
226	            .count();
227	    }
228	
229	    /**
230	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
231	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
232	     * customer-code sequence is derived.
233	     *
234	     * @param city the new owner's city
235	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
236	     */
237	    private void rejectWhenCityAtCapacity(String city) {
238	        long count = this.clinicService.findAllOwners().stream()
239	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
240	            .count();
241	        if (count >= CITY_CAPACITY) {
242	            throw new CityAtCapacityException(city);
243	        }
244	    }
245	
246	    /**
247	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
248	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
249	     * business-day registration date, so the limit is enforced per business day and weekend
250	     * requests count against the Monday they roll forward to.
251	     *
252	     * @param registrationDate the owner's adjusted (business-day) registration date
253	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
254	     *                                  registration date
255	     */
256	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
257	        long count = this.clinicService.findAllOwners().stream()
258	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
259	            .count();
260	        if (count >= DAILY_OWNER_LIMIT) {
261	            throw new DailyOwnerLimitException(registrationDate);
262	        }
263	    }
264	
265	    /**
266	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
267	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
268	     * effective registration date (whether supplied in the request or defaulted to the server date)
269	     * so a weekend value never persists as an owner's {@code registrationDate}.
270	     *
271	     * @param date the effective registration date
272	     * @return the same date when it is a weekday, otherwise the next Monday
273	     */
274	    private LocalDate toBusinessDay(LocalDate date) {
275	        return switch (date.getDayOfWeek()) {
276	            case SATURDAY -> date.plusDays(2);
277	            case SUNDAY -> date.plusDays(1);
278	            default -> date;
279	        };
280	    }
281	
282	    private boolean equalsIgnoreCase(String a, String b) {
283	        return a == null ? b == null : a.equalsIgnoreCase(b);
284	    }
285	
286	    /**
287	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
288	     * offending field so the client learns about all of them at once.
289	     *
290	     * @param ownerFieldsDto the submitted owner fields
291	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
292	     *                                     missing or blank
293	     */
294	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> errors = new ArrayList<>();
296	        if (isBlank(ownerFieldsDto.getFirstName())) {
297	            errors.add("firstName");
298	        }
299	        if (isBlank(ownerFieldsDto.getLastName())) {
300	            errors.add("lastName");
301	        }
302	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
303	            errors.add("address");
304	        }
305	        if (isBlank(ownerFieldsDto.getCity())) {
306	            errors.add("city");
307	        }
308	        if (isBlank(ownerFieldsDto.getTelephone())) {
309	            errors.add("telephone");
310	        }
311	        if (!errors.isEmpty()) {
312	            throw new MissingOwnerFieldsException(errors);
313	        }
314	    }
315	
316	    private boolean isBlank(String value) {
317	        return value == null || value.isBlank();
318	    }
319	
320	    /**
321	     * The number of national (subscriber) digits an E.164 number must carry for a given country
322	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
323	     * national digits and the North American Numbering Plan ('+1') requires 10.
324	     */
325	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
326	        Map.of("61", 9, "1", 10);
327	
328	    /**
329	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
330	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
331	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
332	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
333	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
334	     *
335	     * @param telephone the raw telephone value as submitted
336	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
337	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
338	     *                                   national-number length is wrong for its country code
339	     */
340	    private String normalizeTelephone(String telephone) {
341	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
342	        String nationalSignificantNumber;
343	        if (cleaned.startsWith("+")) {
344	            nationalSignificantNumber = cleaned.substring(1);
345	        } else {
346	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
347	            nationalSignificantNumber = "61" + national;
348	        }
349	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
350	            throw new InvalidTelephoneException(telephone);
351	        }
352	        validateNationalNumberLength(nationalSignificantNumber, telephone);
353	        return "+" + nationalSignificantNumber;
354	    }
355	
356	    /**
357	     * Validates the national-number length of an E.164 number against its country calling code. The
358	     * significant number is a country code immediately followed by the national digits; for each
359	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
360	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
361	     * left unchecked.
362	     *
363	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
364	     * @param rejectedValue             the raw telephone value, reported on rejection
365	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
366	     */
367	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
368	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
369	            String countryCode = rule.getKey();
370	            if (nationalSignificantNumber.startsWith(countryCode)) {
371	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
372	                if (nationalDigits != rule.getValue()) {
373	                    throw new InvalidTelephoneException(rejectedValue);
374	                }
375	                return;
376	            }
377	        }
378	    }
379	
380	    /**
381	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
382	     * value is treated as absent and returns {@code null}); when present the value must be a
383	     * syntactically valid address, and is stored and returned lower-cased.
384	     *
385	     * @param email the raw email value as submitted, may be {@code null}
386	     * @return the lower-cased email, or {@code null} when none was supplied
387	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
388	     */
389	    private String normalizeEmail(String email) {
390	        if (email == null || email.isBlank()) {
391	            return null;
392	        }
393	        String normalized = email.trim().toLowerCase();
394	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
395	            throw new InvalidEmailException(email);
396	        }
397	        return normalized;
398	    }
399	
400	    /**
401	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
402	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
403	     * comparison, so numbers that differ only in formatting still count as duplicates.
404	     *
405	     * @param e164Telephone the E.164 telephone of the owner being created
406	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
407	     */
408	    private void rejectDuplicateTelephone(String e164Telephone) {
409	        boolean inUse = this.clinicService.findAllOwners().stream()
410	            .map(Owner::getTelephone)
411	            .filter(existing -> existing != null)
412	            .map(this::toComparableTelephone)
413	            .filter(existing -> existing != null)
414	            .anyMatch(e164Telephone::equals);
415	        if (inUse) {
416	            throw new DuplicateTelephoneException(e164Telephone);
417	        }
418	    }
419	
420	    /**
421	     * Rejects a lower-cased email that is already used by any other owner, so emails stay unique
422	     * across owners. When the owner being created supplied no email there is nothing to check.
423	     * Existing emails are compared case-insensitively, so values that differ only in case still
424	     * count as duplicates.
425	     *
426	     * @param email the lower-cased email of the owner being created, may be {@code null}
427	     * @throws DuplicateEmailException if another owner already uses the same lower-cased email
428	     */
429	    private void rejectDuplicateEmail(String email) {
430	        if (email == null) {
431	            return;
432	        }
433	        boolean inUse = this.clinicService.findAllOwners().stream()
434	            .map(Owner::getEmail)
435	            .filter(existing -> existing != null)
436	            .anyMatch(existing -> existing.equalsIgnoreCase(email));
437	        if (inUse) {
438	            throw new DuplicateEmailException(email);
439	        }
440	    }
441	
442	    /**
443	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
444	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
445	     * than aborting the whole create.
446	     */
447	    private String toComparableTelephone(String telephone) {
448	        try {
449	            return normalizeTelephone(telephone);
450	        } catch (InvalidTelephoneException ex) {
451	            return null;
452	        }
453	    }
454	
455	    /**
456	     * Applies the household rule to an owner being created. An owner belongs to the same household
457	     * as an existing owner when their lastName and address both match (compared case-insensitively
458	     * with runs of whitespace collapsed to a single space).
459	     *
460	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
461	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
462	     * does, the new owner and every existing owner in the household are assigned the same stable
463	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
464	     *
465	     * @param owner            the owner being created
466	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
467	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
468	     *                                     the request did not opt in with {@code sharesHousehold=true}
469	     */
470	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
471	        String lastNameKey = toHouseholdKey(owner.getLastName());
472	        String addressKey = toHouseholdKey(owner.getAddress());
473	        List<Owner> household = this.clinicService.findAllOwners().stream()
474	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
475	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
476	            .toList();
477	        if (household.isEmpty()) {
478	            return;
479	        }
480	        if (!Boolean.TRUE.equals(sharesHousehold)) {
481	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
482	        }
483	        String householdId = householdId(lastNameKey, addressKey);
484	        owner.setHouseholdId(householdId);
485	        for (Owner existing : household) {
486	            if (!householdId.equals(existing.getHouseholdId())) {
487	                existing.setHouseholdId(householdId);
488	                this.clinicService.saveOwner(existing);
489	            }
490	        }
491	    }
492	
493	    /**
494	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
495	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
496	     * lastName and address keys. Being a pure function of the household, every owner in it derives
497	     * the same value regardless of creation order.
498	     *
499	     * @param lastNameKey the normalized household lastName key
500	     * @param addressKey  the normalized household address key
501	     * @return the household identifier
502	     */
503	    private String householdId(String lastNameKey, String addressKey) {
504	        try {
505	            byte[] digest = MessageDigest.getInstance("SHA-256")
506	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
507	            StringBuilder hex = new StringBuilder(digest.length * 2);
508	            for (byte b : digest) {
509	                hex.append(String.format("%02x", b));
510	            }
511	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
512	        } catch (NoSuchAlgorithmException ex) {
513	            throw new IllegalStateException("SHA-256 not available", ex);
514	        }
515	    }
516	
517	    /**
518	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
519	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
520	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
521	     * string.
522	     */
523	    private String toHouseholdKey(String value) {
524	        if (value == null) {
525	            return "";
526	        }
527	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
528	    }
529	
530	    /**
531	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
532	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
533	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
534	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
535	     * value, or one that is blank once trimmed, normalizes to an empty string.
536	     *
537	     * @param address the raw address value as submitted, may be {@code null}
538	     * @return the normalized address, or an empty string when none was supplied
539	     */
540	    private String normalizeAddress(String address) {
541	        if (address == null) {
542	            return "";
543	        }
544	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
545	        if (collapsed.isEmpty()) {
546	            return "";
547	        }
548	        String[] tokens = collapsed.split(" ");
549	        StringBuilder normalized = new StringBuilder(collapsed.length());
550	        for (int i = 0; i < tokens.length; i++) {
551	            if (i > 0) {
552	                normalized.append(' ');
553	            }
554	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
555	        }
556	        return normalized.toString();
557	    }
558	
559	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
560	    @Override
561	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
562	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
563	        if (currentOwner == null) {
564	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
565	        }
566	        currentOwner.setAddress(ownerFieldsDto.getAddress());
567	        currentOwner.setCity(ownerFieldsDto.getCity());
568	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
569	        currentOwner.setLastName(ownerFieldsDto.getLastName());
570	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
571	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
572	        this.clinicService.saveOwner(currentOwner);
573	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
574	    }
575	
576	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
577	    @Transactional
578	    @Override
579	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
580	        Owner owner = this.clinicService.findOwnerById(ownerId);
581	        if (owner == null) {
582	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
583	        }
584	        this.clinicService.deleteOwner(owner);
585	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
586	    }
587	
588	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
589	    @Override
590	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
591	        Owner owner = this.clinicService.findOwnerById(ownerId);
592	        if (owner == null) {
593	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
594	        }
595	        HttpHeaders headers = new HttpHeaders();
596	        Pet pet = petMapper.toPet(petFieldsDto);
597	        owner.setId(ownerId);
598	        pet.setOwner(owner);
599	        pet.getType().setName(null);
600	        this.clinicService.savePet(pet);
601	        PetDto petDto = petMapper.toPetDto(pet);
602	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
603	            .buildAndExpand(pet.getId()).toUri());
604	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
605	    }
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Override
609	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
610	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
611	        if (currentOwner != null) {
612	            Pet currentPet = this.clinicService.findPetById(petId);
613	            if (currentPet != null) {
614	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
615	                currentPet.setName(petFieldsDto.getName());
616	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
617	                this.clinicService.savePet(currentPet);
618	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
619	            }
620	        }
621	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
622	    }
623	
624	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
625	    @Override
626	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
627	        HttpHeaders headers = new HttpHeaders();
628	        Visit visit = visitMapper.toVisit(visitFieldsDto);
629	        Pet pet = new Pet();
630	        pet.setId(petId);
631	        visit.setPet(pet);
632	        this.clinicService.saveVisit(visit);
633	        VisitDto visitDto = visitMapper.toVisitDto(visit);
634	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
635	            .buildAndExpand(visit.getId()).toUri());
636	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
637	    }
638	
639	
640	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
641	    @Override
642	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
643	        Owner owner = this.clinicService.findOwnerById(ownerId);
644	        if (owner != null) {
645	            Pet pet = owner.getPet(petId);
646	            if (pet != null) {
647	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
648	            }
649	        }
650	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
651	    }
